/**
 * Saudi business documents generated by the free tools: receipt voucher
 * (سند قبض), quotation (عرض سعر) and credit note (إشعار دائن).
 *
 * Totals reuse the Saudi invoice totals (15% VAT, halala rounding) so a
 * quotation converts into the same numbers on the tax invoice.
 *
 * Credit note requirements — ZATCA "Guideline for Tax Invoicing and Records
 * under VAT Provisions", Version 3 (May 2026), §7 "Credit and Debit Notes"
 * (https://zatca.gov.sa/en/HelpCenter/guidelines/Documents/Guideline-for-Tax-Invoicing-and-Records-under-VAT-Provisions.pdf):
 * - the note must comply with the tax invoice requirements of Article 53 of
 *   the VAT Implementing Regulations, specify its type ("Credit Note" /
 *   "Debit Note") and the serial number of the tax invoice it amends
 *   (Article 57 Unified VAT Agreement, Article 54 Implementing Regulations);
 * - it may only be issued for an adjustment to a prior supply, in the cases of
 *   Article 40(1): cancellation/suspension, substantial change in the supply,
 *   change in the agreed value (incl. later discounts), accepted returns, and
 *   errors in the supplier's or customer's information (CREDIT_NOTE_REASONS);
 * - it must be issued no later than 15 days of the month following the event;
 * - ZATCA's sample note shows the original invoice number and date
 *   ("This credit note relates to invoice number (334), issued on …").
 * The e-invoicing XML standard additionally makes the reason (KSA-10) and the
 * billing reference (BT-25) mandatory for Phase 2; this tool produces a PDF.
 */
import { parseLocaleDecimal } from "./numbers";
import { computeInvoiceTotals, type ComputedInvoiceTotals } from "./invoice-totals";
import type { InstantInvoiceDraft } from "./instant-invoice";
import { normalizeSaudiVatNumber, validateSaudiVatNumber } from "./trn-analyzer";

/** Largest amount accepted on a receipt (matches amount-in-words). */
export const MAX_DOCUMENT_AMOUNT = 999_999_999_999.99;

export type DocumentIssue<C extends string> = { code: C; line?: number };
export type DocumentValidation<C extends string> = {
  valid: boolean;
  issues: DocumentIssue<C>[];
};

export interface DocumentLineInput {
  description: string;
  qty: string;
  unitPrice: string;
}

export interface DocumentParty {
  name: string;
  address: string;
  vatNumber: string;
}

const blank = (v: string) => !v.trim();
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function result<C extends string>(issues: DocumentIssue<C>[]): DocumentValidation<C> {
  return { valid: issues.length === 0, issues };
}

/* ------------------------------ Receipt voucher ----------------------------- */

export const RECEIPT_PAYMENT_METHODS = ["cash", "bank_transfer", "cheque", "card"] as const;
export type ReceiptPaymentMethod = (typeof RECEIPT_PAYMENT_METHODS)[number];

export interface ReceiptVoucherInput {
  number: string;
  date: string;
  receivedFrom: string;
  amount: string;
  paymentMethod: ReceiptPaymentMethod;
  chequeNumber: string;
  bankName: string;
  purpose: string;
}

export type ReceiptIssueCode =
  | "NUMBER_REQUIRED"
  | "DATE_REQUIRED"
  | "RECEIVED_FROM_REQUIRED"
  | "AMOUNT_INVALID"
  | "AMOUNT_TOO_LARGE"
  | "CHEQUE_NUMBER_REQUIRED"
  | "BANK_REQUIRED"
  | "PURPOSE_REQUIRED";

export function validateReceiptVoucher(input: ReceiptVoucherInput): DocumentValidation<ReceiptIssueCode> {
  const issues: DocumentIssue<ReceiptIssueCode>[] = [];
  if (blank(input.number)) issues.push({ code: "NUMBER_REQUIRED" });
  if (!ISO_DATE.test(input.date)) issues.push({ code: "DATE_REQUIRED" });
  if (blank(input.receivedFrom)) issues.push({ code: "RECEIVED_FROM_REQUIRED" });
  const amount = parseLocaleDecimal(input.amount.trim());
  if (!Number.isFinite(amount) || amount <= 0 || Math.round(amount * 100) === 0) {
    issues.push({ code: "AMOUNT_INVALID" });
  } else if (amount > MAX_DOCUMENT_AMOUNT) {
    issues.push({ code: "AMOUNT_TOO_LARGE" });
  }
  if (input.paymentMethod === "cheque") {
    if (blank(input.chequeNumber)) issues.push({ code: "CHEQUE_NUMBER_REQUIRED" });
    if (blank(input.bankName)) issues.push({ code: "BANK_REQUIRED" });
  }
  if (blank(input.purpose)) issues.push({ code: "PURPOSE_REQUIRED" });
  return result(issues);
}

/* ---------------------------------- Lines ---------------------------------- */

const lineStarted = (l: DocumentLineInput) => !blank(l.description) || !blank(l.unitPrice);

function completeLines(lines: DocumentLineInput[]): DocumentLineInput[] {
  return lines.filter((l) => {
    const price = parseLocaleDecimal(l.unitPrice);
    const qty = parseLocaleDecimal(l.qty || "1");
    return !blank(l.description) && Number.isFinite(price) && price > 0 && qty > 0;
  });
}

/** 15% VAT totals over the complete lines (same rounding as the Saudi tax invoice). */
export function computeSaudiDocumentTotals(lines: DocumentLineInput[]): ComputedInvoiceTotals {
  return computeInvoiceTotals(
    completeLines(lines).map((l, index) => ({
      description: l.description.trim(),
      qty: l.qty || "1",
      unitPrice: l.unitPrice,
      sortOrder: index,
    })),
  );
}

type LineIssueCode = "LINES_REQUIRED" | "LINE_DESCRIPTION_REQUIRED" | "LINE_PRICE_INVALID" | "LINE_QTY_INVALID";

function lineIssues(lines: DocumentLineInput[]): DocumentIssue<LineIssueCode>[] {
  const issues: DocumentIssue<LineIssueCode>[] = [];
  lines.forEach((l, line) => {
    if (!lineStarted(l)) return;
    if (blank(l.description)) issues.push({ code: "LINE_DESCRIPTION_REQUIRED", line });
    const price = parseLocaleDecimal(l.unitPrice);
    if (!Number.isFinite(price) || price <= 0) {
      issues.push({ code: "LINE_PRICE_INVALID", line });
      return;
    }
    const qty = parseLocaleDecimal(l.qty || "0");
    if (!Number.isFinite(qty) || qty <= 0) issues.push({ code: "LINE_QTY_INVALID", line });
  });
  if (issues.length === 0 && completeLines(lines).length === 0) issues.push({ code: "LINES_REQUIRED" });
  return issues;
}

function vatIssue<C extends string>(vat: string, required: C | null, invalid: C): DocumentIssue<C>[] {
  const normalized = normalizeSaudiVatNumber(vat);
  if (!normalized) return required ? [{ code: required }] : [];
  return validateSaudiVatNumber(normalized) ? [] : [{ code: invalid }];
}

/* -------------------------------- Quotation -------------------------------- */

export interface QuotationInput {
  number: string;
  date: string;
  validUntil: string;
  seller: DocumentParty;
  buyer: DocumentParty;
  lines: DocumentLineInput[];
  terms: string;
}

export type QuotationIssueCode =
  | "NUMBER_REQUIRED"
  | "DATE_REQUIRED"
  | "VALID_UNTIL_BEFORE_DATE"
  | "SELLER_NAME_REQUIRED"
  | "SELLER_VAT_INVALID"
  | "BUYER_NAME_REQUIRED"
  | "BUYER_VAT_INVALID"
  | LineIssueCode;

export function validateQuotation(input: QuotationInput): DocumentValidation<QuotationIssueCode> {
  const issues: DocumentIssue<QuotationIssueCode>[] = [];
  if (blank(input.number)) issues.push({ code: "NUMBER_REQUIRED" });
  if (!ISO_DATE.test(input.date)) issues.push({ code: "DATE_REQUIRED" });
  else if (ISO_DATE.test(input.validUntil) && input.validUntil < input.date) {
    issues.push({ code: "VALID_UNTIL_BEFORE_DATE" });
  }
  if (blank(input.seller.name)) issues.push({ code: "SELLER_NAME_REQUIRED" });
  issues.push(...vatIssue<QuotationIssueCode>(input.seller.vatNumber, null, "SELLER_VAT_INVALID"));
  if (blank(input.buyer.name)) issues.push({ code: "BUYER_NAME_REQUIRED" });
  issues.push(...vatIssue<QuotationIssueCode>(input.buyer.vatNumber, null, "BUYER_VAT_INVALID"));
  issues.push(...lineIssues(input.lines));
  return result(issues);
}

/**
 * Pre-fills the Saudi invoice tool (/tools/fatora) from a quotation. A buyer
 * VAT number means a B2B sale, so the draft becomes a standard tax invoice.
 */
export function quotationToInstantInvoiceDraft(input: QuotationInput): InstantInvoiceDraft {
  const buyerVat = normalizeSaudiVatNumber(input.buyer.vatNumber);
  return {
    invoiceType: buyerVat ? "standard" : "simplified",
    sellerName: input.seller.name.trim(),
    sellerVat: normalizeSaudiVatNumber(input.seller.vatNumber),
    sellerAddress: input.seller.address.trim(),
    clientName: input.buyer.name.trim(),
    clientVat: buyerVat,
    clientAddress: input.buyer.address.trim(),
    notes: "",
    lineItems: completeLines(input.lines).map((l) => ({
      id: crypto.randomUUID(),
      description: l.description.trim(),
      qty: l.qty.trim() || "1",
      unitPrice: l.unitPrice.trim(),
    })),
  };
}

/* ------------------------------- Credit note ------------------------------- */

/** Article 40(1) cases (ZATCA guideline §7.1) plus a free-text "other". */
export const CREDIT_NOTE_REASONS = [
  "cancellation",
  "supply_change",
  "price_change",
  "return",
  "info_error",
  "other",
] as const;
export type CreditNoteReason = (typeof CREDIT_NOTE_REASONS)[number];

export interface CreditNoteInput {
  number: string;
  date: string;
  originalInvoiceNumber: string;
  originalInvoiceDate: string;
  reason: CreditNoteReason | "";
  reasonDetail: string;
  seller: DocumentParty;
  buyer: DocumentParty;
  lines: DocumentLineInput[];
}

export type CreditNoteIssueCode =
  | "NUMBER_REQUIRED"
  | "DATE_REQUIRED"
  | "ORIGINAL_INVOICE_NUMBER_REQUIRED"
  | "ORIGINAL_INVOICE_DATE_REQUIRED"
  | "ORIGINAL_DATE_AFTER_NOTE"
  | "REASON_REQUIRED"
  | "REASON_DETAIL_REQUIRED"
  | "SELLER_NAME_REQUIRED"
  | "SELLER_VAT_REQUIRED"
  | "SELLER_VAT_INVALID"
  | "BUYER_NAME_REQUIRED"
  | "BUYER_VAT_INVALID"
  | LineIssueCode;

export function validateCreditNote(input: CreditNoteInput): DocumentValidation<CreditNoteIssueCode> {
  const issues: DocumentIssue<CreditNoteIssueCode>[] = [];
  if (blank(input.number)) issues.push({ code: "NUMBER_REQUIRED" });
  if (!ISO_DATE.test(input.date)) issues.push({ code: "DATE_REQUIRED" });
  if (blank(input.originalInvoiceNumber)) issues.push({ code: "ORIGINAL_INVOICE_NUMBER_REQUIRED" });
  if (!ISO_DATE.test(input.originalInvoiceDate)) issues.push({ code: "ORIGINAL_INVOICE_DATE_REQUIRED" });
  else if (ISO_DATE.test(input.date) && input.originalInvoiceDate > input.date) {
    issues.push({ code: "ORIGINAL_DATE_AFTER_NOTE" });
  }
  if (!input.reason) issues.push({ code: "REASON_REQUIRED" });
  else if (input.reason === "other" && blank(input.reasonDetail)) {
    issues.push({ code: "REASON_DETAIL_REQUIRED" });
  }
  if (blank(input.seller.name)) issues.push({ code: "SELLER_NAME_REQUIRED" });
  issues.push(
    ...vatIssue<CreditNoteIssueCode>(input.seller.vatNumber, "SELLER_VAT_REQUIRED", "SELLER_VAT_INVALID"),
  );
  if (blank(input.buyer.name)) issues.push({ code: "BUYER_NAME_REQUIRED" });
  issues.push(...vatIssue<CreditNoteIssueCode>(input.buyer.vatNumber, null, "BUYER_VAT_INVALID"));
  issues.push(...lineIssues(input.lines));
  return result(issues);
}
